from random import Random

def count_successes(seed, trials):
    rng = Random(seed)
    return sum(rng.random() < 0.5 for _ in range(trials))

first = count_successes(7, 20)
second = count_successes(7, 20)
assert first == second
record = {'seed': 7, 'trials': 20, 'assumption': 'independent 50% simulated trials', 'successes': first}
